62):\n    print(f\"{year} | {alcohol[year]:,} | {tobacco[year]:,}\")\n    \ntotal_alcohol = sum(alcohol.values())\ntotal_tobacco = sum(tobacco.values())\n\nprint(\"-\" * 35)\nprint(f\"Total | {total_alcohol:,} | {total_tobacco:,}\")\n\n# Calculate percentage difference: (alcohol - tobacco) / tobacco * 100\npercentage_diff = ((total_alcohol - total_tobacco) / total_tobacco) * 100\n\nprint(f\"\\nDifference: {total_alcohol - total_tobacco:,}\")\nprint(f\"Percentage difference (compared to tobacco): {percentage_diff:.4f}%\")\nprint(f\"Rounded to nearest hundredths: {round(percentage_diff, 2)}%\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
